  let candidates = ALLOWED_ACTIONS_BY_STAGE[stage] || ALLOWED_ACTIONS_BY_STAGE.new_lead;
  if (missingFields.length > 0) candidates = ["send_service_menu", "recommend_service", "ask_missing_data", "answer_question", "handoff_human"];
